function Login() {
    var Account = result['账号：'] || Map('账号：');
    var Password = result['密码：'] || Map('密码：');
    if (Account == '' && Password == '') {
        login(String(cache.get(Get('url') + "Account_1")).length > 0 ? (Put(JSON.stringify('【登录提示】\n\n┏┅━┅━┅━┅━┅┅━┅━┅━┅━┅┓\n┋┋' + '\n已退出账号：' + cache.get(Get('url') + "Account_1") + '\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅━┅━┅┛'))) : ('【登录提示】' + '\n\n请输入账号和密码'));
        var headers = JSON.parse(cache.get(Get('url') + "headers").replace('"Referer":"' + Get('url'), '"Referer":"' + Get('url') + '/dynamic/user/'));
        var option = {
            "method": "POST",
            "body": '',
            "headers": String(headers)
        };
        java.ajax(Get('url') + '/dynamic/user/dynamic/user/logout,' + JSON.stringify(option));
        cookie.removeCookie(Get('url'));
        java.webView('', Get('url') + '/user/login', '');
        cache.put(Get('url') + "Account_1",'');
        return;
    } else if (Account == '') {
        login('【登录提示】' + '\n\n请输入账号');
        return;
    } else if (Password == '') {
        login('【登录提示】' + '\n\n请输入密码');
        return;
    } else {
            cookie.removeCookie(Get('url'));
            java.webView('', Get('url') + '/user/login', '');
            var headers = JSON.parse(cache.get(Get('url') + "headers").replace('"Referer":"' + Get('url'), '"Referer":"' + Get('url') + '/dynamic/user/'));
            var option = {
                "method": "GET",
                "headers": String(headers)
            };
            Code = java.getVerificationCode(Get('url') + '/dynamic/kaptcha,' + JSON.stringify(option));
            var requestBody = 'user_name=' + Account + '&user_pwd=' + Password + '&verifyCode=' + Code + '&remeberModule=30';
            var headers = JSON.parse(cache.get(Get('url') + "headers").replace('"Referer":"' + Get('url'), '"Referer":"' + Get('url') + '/user/login'));
            var option = {
                "method": "POST",
                "body": String(requestBody),
                "headers": String(headers)
            };
            Response = java.ajax(Get('url') + '/user/loginHandle,' + JSON.stringify(option));
            if (Response.includes('Success') && Account) {
                let ck = cookie.getCookie(Get('url'));
                let na = ck.includes('user') ? 'Y' : 'N';
                let top = cookie.getKey(baseUrl, 'top_banner_counter_1500') > 0 ? parseInt(cookie.getKey(baseUrl, 'top_banner_counter_1500')) : 0;
                top += 1;
                cookie.setCookie(Get('url'), `${ck};_va=13;__na=${na};top_banner_counter_1500=${top}`);
                cache.put(Get('url') + "Account_1", Account);
                login(Put(JSON.stringify('【登录提示】\n\n┏┅━┅━┅━┅━┅┅━┅━┅━┅━┅┓\n┋┋' + '\n账号：' + Account + '\n┋┋' + '\n❤️登录成功❤️\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅━┅━┅┛')));
            } else {
                cache.put(Get('url') + "Account_1",'');
                login('【登录提示】' + '\n\n♣️登录失败♣️\n\n请检查账号和密码');
            }
    }
}

